window.docContents[40].resolve({"/Planned-constructions/UD-III/#Core-C_________-natural-semantics--Planned-constructions--UD-III":{"contents":"The local reference int& y = x binds a second name to the same location, without allocating.\n\nThe judgment  extends to v[i], o.field, p->field and *p. An index out of bounds and the dereference of nullptr are error.\n\n","context":"Core C++, natural semantics\u0009Planned constructions","header":"5.1. UD III","id":"/Planned-constructions/UD-III/#Core-C_________-natural-semantics--Planned-constructions--UD-III"}});